IF EXISTS(SELECT MASP,TENSP,MALH,MAHANG,SOLUONG,GIANHAP,GIABAN,NGAYNHAP,HINH,MOTA FROM #DemoProducts EXCEPT SELECT MASP,TENSP,MALH,MAHANG,SOLUONG,GIANHAP,GIABAN,NGAYNHAP,HINH,MOTA FROM dbo.SANPHAM) THROW 51401,N'Catalog thiếu hoặc khác snapshot bàn giao.',1;
IF (SELECT COUNT(*) FROM dbo.SANPHAM WHERE MASP BETWEEN N'SB0001' AND N'SB0060')<>60 THROW 51402,N'Sai số lượng SB60.',1;
IF EXISTS(SELECT s.MASP FROM #DemoProducts s JOIN dbo.SANPHAM p ON s.MASP=p.MASP LEFT JOIN dbo.HANG h ON h.MAHANG=p.MAHANG LEFT JOIN dbo.LOAIHANG l ON l.MALH=p.MALH WHERE h.MAHANG IS NULL OR l.MALH IS NULL) THROW 51403,N'Thiếu hãng/loại tham chiếu.',1;
IF EXISTS(SELECT 1 FROM dbo.SANPHAM p JOIN #DemoProducts s ON s.MASP=p.MASP JOIN dbo.HANG h ON p.MAHANG=h.MAHANG JOIN #DemoBrands b ON b.MAHANG=p.MAHANG WHERE h.TENHANG<>b.TENHANG) THROW 51404,N'Tên hãng khác gói bàn giao.',1;
SELECT N'PASS' AS CatalogCheck,COUNT(*) AS Products,COUNT(DISTINCT p.MALH) AS Categories,SUM(CASE WHEN p.MASP IN ('SB0003','SB0004','SB0005','SB0007','SB0008','SB0011','SB0014','SB0015','SB0018','SB0019','SB0020','SB0021','SB0022','SB0023','SB0024','SB0025','SB0027','SB0028','SB0029','SB0030','SB0031','SB0037','SB0043','SB0050','SB0051','SB0052','SB0053','SB0054','SB0055','SB0056') THEN 1 ELSE 0 END) AS RandomAssignedProducts,SUM(CASE WHEN p.SOLUONG=0 THEN 1 ELSE 0 END) AS OutOfStock FROM dbo.SANPHAM p JOIN #DemoProducts s ON s.MASP=p.MASP;
SELECT p.MASP,p.TENSP,p.MALH,h.TENHANG,p.MOTA FROM dbo.SANPHAM p JOIN dbo.HANG h ON h.MAHANG=p.MAHANG WHERE p.MASP IN('SB0004','SB0012','SB0048');
